--Это шаблон SQL-запроса на редактирование стандартной proj.db, исполнять стандартными средствами. Например, через приложение `DB Browser (SQLite)`: Файл - Испорт - База данных из файла SQL.
--Настоящий базовый SQL запрос содержит регистрацию новой геодезической (опорной) СК для СК-63 на базе преобразования Гельмерта для EPSG:1267, также все прочие преобразования Гельмерта для Pulkovo 1942, Pulkovo 1995 обращаются в deprecated=1 (чтобы они не использовались). Также импортируется определение МСК для г. Москвы (МГГТ), т.к. в противном случае потребовалось бы вводить много определений, пусть будет в виде 1 записи (строки WKT)
--Запись в geodetic_datum нового определения для датума на EPSG:1267 (для СК-63 based СК)
insert into "geodetic_datum" (auth_name, code, description, ellipsoid_auth_name, ellipsoid_code, prime_meridian_auth_name, prime_meridian_code, deprecated) VALUES ('MSKRU', 0, 'Pulkovo 1942 (SK 63)', 'Datum for helmert_transformation EPSG:1267', 'EPSG', 7024, 'EPSG', 8901, 0);
--Запись в geodetic_crs нового определения для датума на EPSG:1267 (для СК-63 based СК)
insert into "geodetic_crs" (auth_name, code, name, description, type, coordinate_system_auth_name, coordinate_system_code, datum_auth_name, datum_code, deprecated) VALUES ('MSKRU', 0, 'Pulkovo 1942 (SK 63)', 'For global coordinate system 1963 (with 3,6 degree zones), A...Y', 'geographic 2D', 'EPSG', '6422', 'EPSG', 0, 0);
--Запись в helmert_transformation_table для EPSG:4284 (СК 42 aka Pulkovo 1942) всех остальных преобразований в 1 (deprecated) кроме датума EPSG:5044
update helmert_transformation_table set deprecated = 1 where source_crs_auth_name = 'EPSG' and source_crs_code = '4284' and target_crs_auth_name = 'EPSG' and target_crs_code = '4326';
update helmert_transformation_table set deprecated = 0 where auth_name = 'EPSG' and code = '5044';
--Запись в helmert_transformation_table для EPSG:4200 (СК 95 aka Pulkovo 1995) всех остальных преобразований в 1 (deprecated) кроме датума EPSG:5043
update helmert_transformation_table set deprecated = 1 where source_crs_auth_name = 'EPSG' and source_crs_code = '4200' and target_crs_auth_name = 'EPSG' and target_crs_code = '4326';
update helmert_transformation_table set deprecated = 0 where auth_name = 'EPSG' and code = '5043';
--Импорт определения системы координат для г. Москвы (МГГТ)
insert into "projected_crs" (auth_name, code, name, description, text_definition, deprecated) VALUES ("MSKRU", 379, "Russia-MGGT", "г. Москва МГГТ (МосГорГеоТрест)", 'BOUNDCRS[SOURCECRS[PROJCRS["Russia-MGGT",BASEGEOGCRS["Unknown datum based upon the BESSEL ellipsoid",DATUM["MGGT",ELLIPSOID["Bessel, 1841",6377397.155,299.15281535,LENGTHUNIT["metre",1,ID["EPSG",9001]]]],PRIMEM["Greenwich",0,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8901]]],CONVERSION["Russia-MGGT",METHOD["Transverse Mercator",ID["EPSG",9807]],PARAMETER["Latitude of natural origin",55.66666666667,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8801]],PARAMETER["Longitude of natural origin",37.5,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8802]],PARAMETER["Scale factor at natural origin",1,SCALEUNIT["unity",1],ID["EPSG",8805]],PARAMETER["False easting",16.098,LENGTHUNIT["metre",1],ID["EPSG",8806]],PARAMETER["False northing",14.512,LENGTHUNIT["metre",1],ID["EPSG",8807]]],CS[Cartesian,2],AXIS["(E)",east,ORDER[1],LENGTHUNIT["metre",1,ID["EPSG",9001]]],AXIS["(N)",north,ORDER[2],LENGTHUNIT["metre",1,ID["EPSG",9001]]],USAGE[BBOX[54,34,58,41]]]],TARGETCRS[GEOGCRS["WGS 84",DATUM["World Geodetic System 1984",ELLIPSOID["WGS 84",6378137,298.257223563,LENGTHUNIT["metre",1]]],PRIMEM["Greenwich",0,ANGLEUNIT["degree",0.0174532925199433]],CS[ellipsoidal,2],AXIS["geodetic latitude(Lat)",north,ORDER[1],ANGLEUNIT["degree",0.0174532925199433]],AXIS["geodetic longitude(Lon)",east,ORDER[2],ANGLEUNIT["degree",0.0174532925199433]],ID["EPSG",4326]]],ABRIDGEDTRANSFORMATION["Moscow MGGT Datum",METHOD["Coordinate Frame rotation",ID["EPSG",9607]],PARAMETER["X-axis translation",316.151,ID["EPSG",8605]],PARAMETER["Y-axis translation",78.924,ID["EPSG",8606]],PARAMETER["Z-axis translation",589.65,ID["EPSG",8607]],PARAMETER["X-axis rotation",1.57273000,ID["EPSG",8608]],PARAMETER["Y-axis rotation",-2.69209000,ID["EPSG",8609]],PARAMETER["Z-axis rotation",-2.34693000,ID["EPSG",8610]],PARAMETER["Scale difference",1.0000084507,ID["EPSG",8611]]]]
', 0);
--Преобразование тэгов: ru = MSKRU;by = MSKBY;ua = MSKUA. town, region игнорируются (они только для Autodesk CS Library)
--Таким образом счётчик проекций СК начинается с 1 для MSKRU, с 0 для MSKUA, MSKBY.
--Опорными геодезическими СК для проекций МСК будут: 5044 - EPSG:4200; 5043 - EPSG:4284; 1267 - MSKRU:0.
